import{_ as a,o as e,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Code Walkthrough 2020-07-14: Dmclock","description":"","frontmatter":{"title":"Ceph Code Walkthrough 2020-07-14: Dmclock","date":"2020-07-14T00:00:00.000Z","updated":"2020-07-15T00:00:00.000Z","tags":["Ceph","dmclock算法","分布式存储","QoS","OSD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Code_Walkthrough_2020-07-14_-_Dmclock.md","filePath":"posts/2020/Ceph_Code_Walkthrough_2020-07-14_-_Dmclock.md","lastUpdated":1780459816000}'),i={name:"posts/2020/Ceph_Code_Walkthrough_2020-07-14_-_Dmclock.md"};function c(r,l,h,d,s,p){return e(),o("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议重点讨论了Ceph分布式存储系统中dmclock算法的实现。会议由Eric主持，旨在回顾和讨论dmclock算法在Ceph中的应用和改进。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>dmclock算法介绍</strong>：</p><ul><li>dmclock是一种分布式服务质量（QoS）算法，旨在提高Ceph中OSD（对象存储守护进程）的公平性。</li><li>该算法基于mclock算法，并进行了分布式扩展，称为dmclock。</li></ul></li><li><p><strong>算法实现细节</strong>：</p><ul><li>dmclock算法作为库实现，包含头文件和模板化代码，适用于多种场景。</li><li>算法核心在于客户端和服务器端的交互，服务器不共享客户端信息，客户端负责跟踪服务历史。</li></ul></li><li><p><strong>代码结构和组织</strong>：</p><ul><li>dmclock代码作为Ceph的子模块，包含客户端和服务器端的实现。</li><li>代码中使用了间接侵入式堆数据结构来管理客户端请求的优先级。</li></ul></li><li><p><strong>性能和优化</strong>：</p><ul><li>讨论了dmclock算法在Ceph中的性能表现和潜在的优化点。</li><li>指出了一些操作可能较为昂贵，例如通过过滤移除请求的操作。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了dmclock算法在Ceph中的重要性和当前的实现状态。</li><li>讨论了算法的性能和可能的改进方向。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化dmclock算法的性能，特别是在处理请求过滤和移除操作方面。</li><li>鼓励社区成员参与dmclock算法的讨论和改进。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到了几位关键开发者（如Sam、Casey、Abhishek）在dmclock算法上的贡献。</li><li>Eric表示愿意回答关于dmclock算法的具体问题，尽管他可能需要一些时间来回顾相关细节。</li></ul><p>本次会议为Ceph社区成员提供了一个深入了解和讨论dmclock算法的机会，有助于推动该算法在Ceph中的进一步应用和优化。</p>',12)])])}const u=a(i,[["render",c]]);export{_ as __pageData,u as default};
